/** Whether this entity is a temporary registration (and not a business). */
get isTemporaryRegistration (): boolean {
  return !!sessionStorage.getItem('TEMP_REG_NUMBER')
}

/** Whether to show the history panel. */
get showHistoryPanel () {
  return (this.getFilings.length > 0)
}

def get_registration_filing(business):
    """Return the registration filing for the business."""
    if len(registration_filings := Filing.get_filings_by_types(business.id, ['registration'])) <= 0:
        return None

    return registration_filings[0]


def get_account_id(_, account_id: str = None) -> str:
    """Return the account id."""
    return account_id or request.headers.get('Account-Id', None)

create table if not exists correction
(
    event_id            numeric(9)  not null
        constraint fk_correction_filing
            references filing (event_id),
    corp_num            varchar(10) not null
        constraint fk_correction_corporation
            references corporation (corp_num),
    associated_doc_desc varchar(4000)
);

comment on table correction is 'new table\n\nAny correction filings completed appear to have this kind of entry, which includes BC Companyies, and the details show on the filing history on the ledger.';

alter table correction
    owner to postgres;
